# MinIO S3 API — storage.example.com
server {
    listen 443 ssl;
    server_name storage.example.com;

    client_max_body_size 200m;   # large images and PDF uploads
    proxy_request_buffering off; # stream multipart/PUT uploads

    location / {
        proxy_pass http://127.0.0.1:9000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 60s;
        proxy_read_timeout 300s;
    }
}

# MinIO Console — console-storage.example.com
server {
    listen 443 ssl;
    server_name console-storage.example.com;

    location / {
        proxy_pass http://127.0.0.1:9001;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 300s;
    }
}
